# HPE community post on MLPerf Inference v5.1, held against the v5.0 and v5.1 result files. python3 -I check_claims_hpe_v51.py
import json,hashlib,re
FILES=['raw/inf_5.0.json','raw/inf_5.1.json']; RAW={f:open(f,'rb').read() for f in FILES}
V5=json.loads(RAW[FILES[0]]); V1=json.loads(RAW[FILES[1]]); s=str; pc=lambda x,y:100*(x/y-1); P=lambda x:x['Performance_Result']
import re as _re
_KEEP={'bert','rgat','retinanet','resnet','dlrm','unet','sdxl'}
def _and(L): return L[0] if len(L)==1 else ', '.join(L[:-1])+' and '+L[-1]
def _pl(s,prose=False):   # a table cell as plain text: no semicolons, and in the data cells no Python list, True/False or None
    if not isinstance(s,str): return s
    if not prose:
        s=_re.sub(r"\[((?:'[^']*'(?:, )?)+)\]",lambda m:_and(_re.findall(r"'([^']*)'",m.group(1))),s).replace('[]','none')
        s=_re.sub(r'\bTrue\b','yes',s); s=_re.sub(r'\bFalse\b','no',s); s=_re.sub(r'\bNone\b','none',s)
    return _re.sub(r'; ([a-z]+)\b(?![-_./])',lambda m:'. '+(m.group(1) if m.group(1) in _KEEP else m.group(1).capitalize()),s).replace('; ','. ')
def n(x):
    m=re.findall(r'\(x(\d+)\)',s(x.get('Accelerator'))); return sum(map(int,m)) if m else int(x.get('a#') or 0)*int(x.get('Nodes') or 1)
def mk(i,q,calc,st,got,out,note): return dict(id=i,quote=q,calc=_pl(calc),stated=_pl(st),delivered=_pl(got),outcome=out,note=_pl(note,True),label_mismatch=False)
D=[x for x in V1 if x['Category']=='closed' and 'datacenter' in x['Suite']]; D5=[x for x in V5 if x['Category']=='closed' and 'datacenter' in x['Suite']]
def e(L,i,m,sc): r=[x for x in L if x['ID']==i and x['Model']==m and x['Scenario']==sc]; assert len(r)==1,(i,m,sc,len(r)); return r[0]
pcie=lambda x:'SXM' not in s(x['Accelerator']) and not any(g in s(x['Accelerator']) for g in ('GH200','GB200','GB300'))
HV=[]
ds,d9=e(D,'5.1-0050','dlrm-v2-99','Server'),e(D,'5.1-0050','dlrm-v2-99.9','Server')
HV.append(mk('HV1','the DL380a achieved two overall #1 spots in the DLRM-v2-99 and DLRM-v2-99.9 benchmarks (Server scenario) with 65,021 and 41,357 queries/second per GPU, respectively','HPE entry 5.1-0050 (10 H200 NVL), DLRM Server result divided by 10, then ranked among closed datacenter v5.1 entries','#1 in both, 65,021 and 41,357 per GPU',f'{P(ds)/n(ds):,.0f} and {P(d9)/n(d9):,.1f} per GPU','CONSISTENT' if (round(P(ds)/n(ds)),round(P(d9)/n(d9)))==(65021,41357) or (round(P(ds)/n(ds)),round(P(d9)/n(d9)+0.5))==(65021,41357) else 'BELOW','Values are the file results divided by ten accelerators.'))
def rank(L,m,sc,v,key):
    g=sorted([key(x) for x in L if x['Model']==m and x['Scenario']==sc],reverse=True); return 1+sum(1 for t in g if t>v),len(g)
pg=lambda x:P(x)/max(n(x),1)
r1=rank(D,'dlrm-v2-99','Server',pg(ds),pg); r2=rank(D,'dlrm-v2-99.9','Server',pg(d9),pg); t1=rank(D,'dlrm-v2-99','Server',P(ds),P); t2=rank(D,'dlrm-v2-99.9','Server',P(d9),P)
HV.append(mk('HV2','the DL380a achieved two overall #1 spots in the DLRM-v2-99 and DLRM-v2-99.9 benchmarks (Server scenario)','HPE entry 5.1-0050 ranked among closed datacenter v5.1 DLRM Server entries, by result per accelerator and by total result','overall #1 in DLRM-v2-99 and DLRM-v2-99.9 Server',f'per accelerator: rank {r1[0]} of {r1[1]} and {r2[0]} of {r2[1]}; by total result: rank {t1[0]} of {t1[1]} and {t2[0]} of {t2[1]}','CONSISTENT' if r1[0]==1 and r2[0]==1 else 'BELOW','The post quotes the figures per GPU. By total system result HPE is first in DLRM-v2-99 Server. Per GPU it is not first in either.'))
o5=e(D5,'5.0-0043','dlrm-v2-99','Offline'); ro=rank(D5,'dlrm-v2-99','Offline',P(o5),P); rg=rank(D5,'dlrm-v2-99','Offline',pg(o5),pg)
nxt=sorted([P(x) for x in D5 if x['Model']=='dlrm-v2-99' and x['Scenario']=='Offline' and x['ID']!='5.0-0043'],reverse=True)[0]
HV.append(mk('HV3','where it performed 57% better than the next-best submission in the DLRM-v2-99 Offline scenario','HPE entry 5.0-0043 DLRM-v2-99 Offline against the other closed datacenter v5.0 entries','57% better than the next-best',f'{P(o5):,.0f}; rank {ro[0]} of {ro[1]} by total, {rg[0]} of {rg[1]} per accelerator; the highest other entry is {nxt:,.0f} ({pc(P(o5),nxt):+.1f}%)','CANNOT_TELL','No ranking by total or per accelerator gives +57%. The group the post compares against is not named, so the file cannot settle it.'))
nx=sorted([P(x) for x in D if x['Model']=='dlrm-v2-99' and x['Scenario']=='Server' and x['ID']!='5.1-0050'],reverse=True)[0]
HV.append(mk('HV4','In this new round, v5.1, it continued to dominate, outperforming competitors by 29% in the DLRM-v2-99 Server test, showcasing consistent excellence over multiple benchmark iterations.','HPE entry 5.1-0050 DLRM-v2-99 Server against the next closed datacenter v5.1 entry','outperforming competitors by 29%',f'{P(ds):,.0f} against the next entry {nx:,.0f} ({pc(P(ds),nx):+.1f}%)','CANNOT_TELL','The next entry by total result is 10% lower. The group the 29% is taken against is not named.'))
dl=[x for x in D if x['ID']=='5.1-0051' and x['Model']=='llama3.1-8b' and x['Scenario']=='Server'][0]; ci=e(D,'5.1-0011','llama3.1-8b','Server')
g8=sorted([(P(x),x['Submitter']) for x in D if x['Model']=='llama3.1-8b' and x['Scenario']=='Server' and n(x)==8 and pcie(x)],reverse=True)
HV.append(mk('HV5','In the MLPerf Inference v5.1 Llama3.1 8B test (Server scenario), the DL380a Gen12 claimed the top spot among systems with eight PCIe-based GPUs, delivering an impressive 46,060.0 tokens/second and outperforming Cisco\'s UCS C845A M8 by 19%, with its 38,696.9 tokens/second result.','HPE entry 5.1-0051 and Cisco entry 5.1-0011, Llama 3.1 8B Server, against closed datacenter v5.1 entries with eight non-SXM accelerators','top among eight PCIe GPU systems, 46,060.0 against 38,696.9, +19%',f'HPE {P(dl):,.1f} ({dl["System"]}), Cisco {P(ci):,.1f}, {pc(P(dl),P(ci)):+.1f}%; top of {len(g8)} eight-GPU PCIe entries: {g8[0][1]} {g8[0][0]:,.1f}, next {g8[1][1]} {g8[1][0]:,.1f}','CONSISTENT' if g8[0][1]=='HPE' and round(pc(P(dl),P(ci)))==19 else 'BELOW','Our rule: PCIe means an accelerator that is not SXM and not a Grace system.'))
dl3=[x for x in D5 if x['ID']=='5.0-0046' and x['Scenario']=='Offline' and x['Model']=='llama2-70b-99'][0]; dd=[x for x in D5 if x['ID']=='5.0-0018' and x['Scenario']=='Offline' and x['Model']=='llama2-70b-99'][0]
l40=sorted([(P(x),x['Submitter']) for x in D5 if x['Model']=='llama2-70b-99' and x['Scenario']=='Offline' and 'L40S' in s(x['Accelerator']) and n(x)==8],reverse=True)
HV.append(mk('HV6','Both the DL380a Gen12 and Dell\'s PowerEdge XE7745, equipped with eight NVIDIA L40S GPUs, competed in this benchmark, with the DL380a delivering 3655.89 tokens/second compared to Dell\'s 3481.53 tokens/second.','HPE entry 5.0-0046 and Dell entry 5.0-0018, Llama 2 70B 99 Offline','3655.89 and 3481.53, only two eight-L40S entries',f'{P(dl3):,.2f} and {P(dd):,.2f}; eight-L40S entries in v5.0: '+_and([f'{b} {a:,.2f}' for a,b in l40]),'CONSISTENT' if (round(P(dl3),2),round(P(dd),2))==(3655.89,3481.53) and len(l40)==2 else 'BELOW',''))
f6=[x for x in V5 if x['ID']=='5.0-0051'][0]; f7=[x for x in V5 if x['ID']=='5.0-0011'][0]; f8=[x for x in V5 if x['ID']=='5.0-0038'][0]
l31=[x for x in V5 if x['Model']=='llama3.1-8b']
HV.append(mk('HV7','6 MLPerf Inference: Datacenter v5.0 Closed. Llama3.1-8b benchmark. Submission ID 5.0-0051 ... 7 MLPerf Inference: Datacenter v5.0 Closed. Llama3.1-8b benchmark. Submission ID 5.0-0011 ... 8 MLPerf Inference: Datacenter v5.0 Closed. Llama2 70B benchmark. Submission ID 5.0-0038','entries 5.0-0051, 5.0-0011 and 5.0-0038 in the v5.0 file','footnotes 6 and 7 cite v5.0 Llama3.1-8b entries, footnote 8 cites an HPE DL380a Llama 2 70B entry',f'5.0-0051 is {f6["Submitter"]} {f6["System"]}; 5.0-0011 is {f7["Submitter"]} {f7["System"]}; v5.0 Llama3.1-8b rows in the file: {len(l31)}; 5.0-0038 is {f8["Submitter"]} {f8["System"]}','BELOW','The v5.0 file has no Llama3.1-8b rows. The 46,060.0 and 38,696.9 results are v5.1 entries 5.1-0051 and 5.1-0011. The DL380a L40S Llama 2 70B entry is 5.0-0046.'))
w=e(D,'5.1-0052','whisper','Offline'); wp=sorted([(P(x)/n(x),x['Submitter'],x['ID']) for x in D if x['Model']=='whisper' and x['Scenario']=='Offline' and n(x)>0 and pcie(x)],reverse=True)
HV.append(mk('HV8','the HPE ProLiant DL385 Gen11 immediately secured a #1 spot, delivering the best per-GPU performance for a PCIe-based system in the new speech-to-text Whisper benchmark, with 3962.78 samples/second per GPU, when equipped with NVIDIA H200 NVL 141GB GPUs','HPE entry 5.1-0052 Whisper Offline divided by 2, against closed datacenter v5.1 Whisper entries with non-SXM accelerators','best per-GPU for a PCIe system, 3962.78 per GPU',f'{P(w)/n(w):,.2f} per GPU; top PCIe entry per GPU {wp[0][1]} {wp[0][0]:,.2f} ({wp[0][2]}), next {wp[1][1]} {wp[1][0]:,.2f}','CONSISTENT' if wp[0][2]=='5.1-0052' and round(P(w)/n(w),2)==3962.78 else 'BELOW','Our rule: PCIe means an accelerator that is not SXM and not a Grace system.'))
rtx={x['Submitter'] for x in V1 if 'RTX PRO 6000' in s(x['Accelerator'])+s(x['System'])}
HV.append(mk('HV9','HPE was the only company to submit a server utilizing the NVIDIA RTX PRO 6000 Blackwell Server Edition GPU in this round of MLPerf Inference testing.','v5.1 file entries naming RTX PRO 6000','only HPE',f'submitters: {sorted(rtx)}','CONSISTENT' if rtx=={'HPE'} else 'BELOW',''))
g1,g2=e(D,'5.1-0053','dlrm-v2-99','Server'),e(D,'5.1-0053','dlrm-v2-99','Offline'); gh={x['Submitter'] for x in V1 if 'GH200' in s(x['Accelerator'])}
HV.append(mk('HV10','The HPE ProLiant DL384 Gen12, equipped with NVIDIA GH200 NVL2 accelerators, stood out in the DLRM-v2-99 benchmark, achieving 161,030 queries per second (Server scenario) and 174,456 samples per second (Offline scenario), making HPE the only vendor to submit results with this advanced configuration.','HPE entry 5.1-0053 and every v5.1 entry with a GH200 accelerator','161,030 Server, 174,456 Offline, only vendor',f'{P(g1):,.0f} and {P(g2):,.0f}; v5.1 submitters with GH200: {sorted(gh)}','CONSISTENT' if (round(P(g1)),round(P(g2)))==(161030,174456) and gh=={'HPE'} else 'BELOW',''))
m1=[x for x in D+[y for y in V1 if y['Suite']=='edge' and y['Category']=='closed'] if x['ID']=='5.1-0054']; mo=[x for x in m1 if x['Scenario']=='Offline' and x['Model']=='retinanet'][0]; mm=[x for x in m1 if x['Scenario']=='MultiStream' and x['Model']=='retinanet'][0]
HV.append(mk('HV11','In the edge scenario, HPE ProLiant ML30 Gen11 displayed strong throughput performance in RetinaNet benchmark tests, delivering 258.352 samples/second and multistream latency = 29.96 ms on a single NVIDIA RTX 4000 Ada 20GB GPU.','HPE entry 5.1-0054, Retinanet Offline and MultiStream','258.352 samples/s, 29.96 ms, one RTX 4000 Ada',f'{P(mo):.3f} Offline, {P(mm):.2f} ms MultiStream, {n(mo)} accelerator, {mo["Accelerator"]}','CONSISTENT' if (round(P(mo),3),round(P(mm),2),n(mo))==(258.352,29.96,1) else 'BELOW',''))
def sx(m,sc): return sorted([(P(x),x['Submitter'],x['ID']) for x in D if x['Model']==m and x['Scenario']==sc and 'H200-SXM' in s(x['Accelerator']) and n(x)==8],reverse=True)
chk=[('retinanet','Offline',14996.6),('llama3.1-8b','Server',64914.6),('llama3.1-8b','Offline',66036.8),('mixtral-8x7b','Server',60955.1),('mixtral-8x7b','Offline',62108.4),('whisper','Offline',34450.7)]
okc=all(sx(m,sc)[0][2]=='5.1-0049' and round(sx(m,sc)[0][0],1)==v for m,sc,v in chk)
HV.append(mk('HV12','#1 in RetinaNet (Offline) with 14,996.6 samples per second ... # 1 in the new Llama3.1-8B (Server and Offline), with 64,914.6 and 66,036.8 tokens per second ... #1 in Mixtral-8x7B (Server and Offline), delivering 60,955.1 and 62,108.4 tokens per second ... #1 in the new Whisper (Offline) with 34,450.7 samples per second','HPE entry 5.1-0049 (8 H200 SXM) against closed datacenter v5.1 entries with eight H200 SXM, six model and scenario pairs','six first places with the printed values',', '.join(f'{m} {sc} {sx(m,sc)[0][0]:,.1f} ({sx(m,sc)[0][1]}, next {sx(m,sc)[1][0]:,.1f})' for m,sc,v in chk),'CONSISTENT' if okc else 'BELOW','Our rule: first among the entries with eight H200 SXM accelerators.'))
s1,o1=sx('llama3.1-8b','Server'),sx('llama3.1-8b','Offline')
HV.append(mk('HV13','These results are 12% higher (Server) and 16% (Offline) than the nearest competitor\'s entry using the same number of NVIDIA H200 SXM GPUs.','HPE entry 5.1-0049 Llama3.1-8B against the next entry with eight H200 SXM','+12% Server, +16% Offline',f'Server {s1[0][0]:,.1f} over {s1[1][0]:,.1f} ({s1[1][1]}), {pc(s1[0][0],s1[1][0]):+.1f}%. Offline {o1[0][0]:,.1f} over {o1[1][0]:,.1f} ({o1[1][1]}), {pc(o1[0][0],o1[1][0]):+.1f}%','CONSISTENT' if round(pc(s1[0][0],s1[1][0]))==12 and round(pc(o1[0][0],o1[1][0]))==16 else 'BELOW','Server reproduces at 12.0%. Offline is 13.3%, not 16%.'))
ds1=[x for x in V1 if x['Model']=='deepseek-r1' and x['Scenario']=='Offline' and 'H200' in s(x['Accelerator'])]
HV.append(mk('HV14','The only system featuring NVIDIA H200 GPUs to publish DeepSeek-R1 Offline performance of 8904.83 tokens per second, which was submitted in the Datacenter-Open category.','v5.1 DeepSeek-R1 Offline entries on H200','only H200 DeepSeek-R1 Offline entry, 8904.83, open division',f'{len(ds1)} entries: '+', '.join(f'{x["Submitter"]} {x["ID"]} {x["Category"]} {P(x):,.2f}' for x in ds1),'CONSISTENT' if len(ds1)==1 and round(P(ds1[0]),2)==8904.83 and ds1[0]['Category']=='open' else 'BELOW',''))
HV.append(mk('HV15','demonstrated leadership in AI inferencing with fourteen #1 results across multiple scenarios in the Datacenter and Edge categories','the first-place results reproduced in this script','fourteen #1 results',f'the post counts eight ProLiant results and six XD670 results. Six XD670 results reproduce (HV12). The ProLiant ones are not all reproduced by our rule: per accelerator DLRM is not first (HV2), Llama3.1-8B Server and Whisper per GPU are (HV5, HV8)','CANNOT_TELL','The rules used for the other first places, such as Xeon with NVIDIA groups in Figure 2, are in figures, not text.'))
x5=[(P(x),x['Submitter'],x['ID']) for x in D5 if x['Model']=='retinanet' and x['Scenario']=='Offline' and 'H100-SXM' in s(x['Accelerator']) and n(x)==8]; x5.sort(reverse=True)
HV.append(mk('HV16','following a #1 result in this same model during the prior round of benchmark tests','v5.0 Retinanet Offline entries with eight H100 SXM, footnote 16 IDs 5.0-0039 and 5.0-0040','#1 in v5.0 among eight H100 SXM','top three: '+_and([f'{b} {a:,.1f} ({c})' for a,b,c in x5[:3]]),'CONSISTENT' if x5[0][1]=='HPE' else 'BELOW','Footnote 16 names HPE entries 5.0-0039 and 5.0-0040, which are the top two.'))
